usage.threejs:
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js'

const loader = new GLTFLoader()
loader.load('https://cdn.3dassets.dev/assets/25270/v1/model.glb', (gltf) => {
  scene.add(gltf.scene)
})

usage.r3f:
import { useGLTF } from '@react-three/drei'

export function SeatedDisplayMannequinRetailStoreFixturesAndMall(props) {
  const { scene } = useGLTF('https://cdn.3dassets.dev/assets/25270/v1/model.glb')
  return <primitive object={scene} {...props} />
}
useGLTF.preload('https://cdn.3dassets.dev/assets/25270/v1/model.glb')

usage.unity:
// Unity: import model.glb with glTFast (Package Manager: com.unity.cloud.gltfast) and drag the prefab in,
